// FILE: pokemonList.shiny.js
// UPDATED (2026-03-12)
//
// CHANGES
// - CHANGED: Expanded each Pokemon entry to include both `sprite` and `shinySprite`.
// - ADDED: `buildShinySpriteUrl` helper to derive shiny Home sprite URLs from the existing normal URLs.
// - ADDED: `getPokemonDisplaySprite` helper for normal vs shiny display selection.
// - ADDED: `mapPokemonListWithDisplaySprites` helper for pre-resolving a whole list with display sprites.
// - NOTE: Keeps `sprite` as the normal sprite so existing code that reads `pokemon.sprite` will still work.


function buildShinySpriteUrl(normalSpriteUrl) {
  if (typeof normalSpriteUrl !== "string" || !normalSpriteUrl.length) {
    return normalSpriteUrl;
  }

  // CHANGED: Reuse the existing Pokemon DB Home path structure and only swap `/normal/` for `/shiny/`.
  return normalSpriteUrl.replace("/sprites/home/normal/", "/sprites/home/shiny/");
}

export function getPokemonDisplaySprite(pokemon, options = {}) {
  const {
    shinyChance = 0.05,
    forceShiny = null,
    rng = Math.random,
  } = options;

  // ADDED: Allow callers to force shiny on/off for previews, testing, or special UI cases.
  const isShiny =
    typeof forceShiny === "boolean" ? forceShiny : rng() < shinyChance;

  const normalSprite = pokemon?.sprite ?? null;
  const shinySprite = pokemon?.shinySprite ?? buildShinySpriteUrl(normalSprite);

  return {
    ...pokemon,
    displaySprite: isShiny && shinySprite ? shinySprite : normalSprite,
    isShiny,
  };
}

export function mapPokemonListWithDisplaySprites(list, options = {}) {
  if (!Array.isArray(list)) return [];

  return list.map((pokemon) => getPokemonDisplaySprite(pokemon, options));
}

